const now = new Date();
const since = new Date(now.getTime() - ($input.first().json.lookback_days * 86400000));
const sinceISO = since.toISOString();
const owner = $input.first().json.github_owner;
const repo = $input.first().json.github_repo;
return [{json: {
  ...$input.first().json,
  since_date: sinceISO,
  date_range: `${since.toISOString().split('T')[0]} to ${now.toISOString().split('T')[0]}`,
  api_base: `https://api.github.com/repos/${owner}/${repo}`
}}];

const config = $('Calculate Dates').first().json;
const commitsRaw = $('Fetch Commits').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const issuesRaw = $('Fetch Closed Issues').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const prsRaw = $('Fetch Merged PRs').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);

const since = new Date(config.since_date);
const mergedPRs = prsRaw.filter(pr => pr.merged_at && new Date(pr.merged_at) >= since);
const closedIssues = issuesRaw.filter(i => !i.pull_request);

// Contributor stats
const contributors = {};
commitsRaw.forEach(c => {
  const author = c.commit?.author?.name || c.author?.login || 'unknown';
  if (!contributors[author]) contributors[author] = {commits: 0, name: author};
  contributors[author].commits++;
});
mergedPRs.forEach(pr => {
  const author = pr.user?.login || 'unknown';
  if (!contributors[author]) contributors[author] = {commits: 0, name: author};
  contributors[author].prs = (contributors[author].prs || 0) + 1;
});

const topContributors = Object.values(contributors)
  .sort((a,b) => (b.commits + (b.prs||0)) - (a.commits + (a.prs||0)))
  .slice(0, 10);

const commits = commitsRaw.map(c => ({
  sha: c.sha?.substring(0,7),
  message: c.commit?.message?.split('\n')[0] || '',
  author: c.commit?.author?.name || c.author?.login || 'unknown',
  date: c.commit?.author?.date
}));

const issues = closedIssues.map(i => ({
  number: i.number, title: i.title,
  labels: (i.labels || []).map(l => l.name),
  closed_at: i.closed_at
}));

const pulls = mergedPRs.map(pr => ({
  number: pr.number, title: pr.title,
  author: pr.user?.login,
  merged_at: pr.merged_at,
  additions: pr.additions || 0,
  deletions: pr.deletions || 0
}));

return [{json: {
  owner: config.github_owner,
  repo: config.github_repo,
  language: config.language,
  delivery_method: config.delivery_method,
  date_range: config.date_range,
  summary: {
    total_commits: commits.length,
    total_issues_closed: issues.length,
    total_prs_merged: pulls.length,
    top_contributors: topContributors
  },
  commits, issues, pulls
}}];

let summary = '';
try {
  const response = $input.first().json;
  if (response.content && response.content[0]) {
    summary = response.content[0].text;
  } else if (typeof response === 'string') {
    summary = response;
  } else {
    summary = JSON.stringify(response);
  }
} catch(e) {
  summary = '⚠️ Error extracting summary: ' + e.message;
}

const prev = $('Aggregate Data').first().json;
const header = `# 📊 Weekly Dev Summary\n**${prev.owner}/${prev.repo}** | ${prev.date_range}\n\n---\n\n`;

return [{json: {
  summary: header + summary,
  delivery_method: prev.delivery_method,
  owner: prev.owner,
  repo: prev.repo,
  date_range: prev.date_range
}}];

const error = $input.first().json;
const timestamp = new Date().toISOString();
const errorMsg = `⚠️ Weekly Summary Generation Failed\n\nTime: ${timestamp}\nError: ${JSON.stringify(error, null, 2)}\n\nPlease check your API credentials and network connectivity.`;
return [{json: {summary: errorMsg, delivery_method: 'discord', owner: 'unknown', repo: 'unknown', date_range: 'N/A'}}];
